#include <iostream>
#include <utility>

struct S {
    S() { std::cout << "ctor\n"; }
    S(const S&) { std::cout << "copy\n"; }
    S(S&&) noexcept { std::cout << "move\n"; }
};

void take(S) {}

int main() {
    S s;
    take(s);
    take(std::move(s));
    return 0;
}

